KG42.register("rules-1ae5859e70321ae9efcfee67",{"id":"05-double_auction::v141-c-R025","paper":"05-double_auction","record":{"rule_id":"v141-c-R025","mechanism_id":"v141-a-M04","name":"Market payment","process_stage":"settlement","market_meaning":"Local TR transaction prices determine buyers' payment rates as B_γ^P and sellers' receipt rates as S_γ^P. Scope: Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["pricing.local","settlement.payment"],"E":[{"edge_id":"v141-c-R025-E001","source":"pricing.local","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R025-C001"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},"x":[],"theta":[{"parameter_id":"v141-c-R025-theta-BgammaP","symbol":"B_{\\gamma}^{P}","meaning":"TR transaction price paid by trading buyers: the bid price at the largest breakeven index gamma. Fixed input to the settlement/payment rule, produced at the pricing stage.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":["\\gamma"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},{"parameter_id":"v141-c-R025-theta-SgammaP","symbol":"S_{\\gamma}^{P}","meaning":"TR transaction price received by trading sellers: the ask price at the largest breakeven index gamma. Fixed input to the settlement/payment rule, produced at the pricing stage.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":["\\gamma"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]}],"phi":[{"constraint_id":"v141-c-R025-C001","kind":"mathematical","role":"core","statement":"Local TR transaction prices determine buyers' payment rates as B_γ^P and sellers' receipt rates as S_γ^P. Scope: Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","expression":"\\text{Buyer payment rate} = B_{\\gamma}^{P}, \\quad \\text{Seller receipt rate} = S_{\\gamma}^{P}","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R025-theta-BgammaP","v141-c-R025-theta-SgammaP"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]}],"pi":[{"evidence_id":"v141-b-g01-ev-06","location":{"location_id":"src-22913ad574-p02-c2r4__v141-a-M04-pricing","page":2,"printed_page":null,"section":"2.1","anchor_text":"a y g g p s- does not exist for each auction interval. of Uniform k-DA is a variation to discriminat","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"Table 1 Auction mechanisms. TR | Price trading buyers pay: $B_{\\gamma}^P$ | Price trading sellers receive: $S_{\\gamma}^P$"},{"evidence_id":"v141-b-g01-ev-08","location":{"location_id":"src-22913ad574-p03-c1r2__v141-a-M04-clearing","page":3,"printed_page":null,"section":"2.1","anchor_text":"of trades while maintaining truthful bidding by limiting trades to 1 Ta buyers and sellers [45]. Suc","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Trade Reduction (TR) auction mechanism avoids subsidization of trades while maintaining truthful bidding by limiting trades to $\\gamma - 1$ buyers and sellers [45]. Such differs from uniform k-DA and VCG, where $\\gamma$ buyers and sellers are allowed to transact. Because buyer $\\gamma$ and seller $\\gamma$ are not permitted to participate in the TR auction, social welfare is not maximized. However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$. As $B_{\\gamma}^P \\geq S_{\\gamma}^P$, the market operator may financially gain $B_{\\gamma}^P - S_{\\gamma}^P$ from each single unit transaction."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"The settlement/payment rule introduces no new design or operational decision variable: within this rule the TR transaction prices B_gamma^P and S_gamma^P are given inputs (represented as parameters theta) from the pricing stage, and the buyer payment rate and seller receipt rate are definitionally set equal to those prices (payment = B_gamma^P, receipt = S_gamma^P). Any bid/ask decision role for B^P and S^P lies in the bidding/pricing stages, not in this settlement rule, and is not carried across.","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M04-clearing","v141-a-M04-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-ev-06","quote":"TR | Price trading buyers pay: $B_{\\gamma}^P$ | Price trading sellers receive: $S_{\\gamma}^P$"},{"evidence_id":"v141-b-g01-ev-08","quote":"However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$."}]],"C2_formalization":{"graph_sha256":"d70bbf46b352283107e80d846a7d5cacb30276c3f180f78a26a546f2f198c599","applicability":"formalized","reason":"Rule v141-c-R025 (TR Market payment) specifies that TR settlement payments are the TR transaction prices: trading buyers pay B_gamma^P and trading sellers receive S_gamma^P (Table 1 and page-3 text, ev-06/ev-08). This is an actual supported expression, so the single existing constraint is formalized as a mathematical mapping in which the TR transaction prices B_gamma^P and S_gamma^P are given inputs (parameters theta) and the buyer payment rate and seller receipt rate are definitionally set equal to them. The frozen vertices pricing.local and settlement.payment and edge v141-c-R025-E001 (links) already represent this price-to-payment relation, so no graph revision is required. The scope (trading buyers and sellers under the TR payment rule) is retained. Per the experiment's source_review_policy, the B evidence (v141-b-g01-ev-06, v141-b-g01-ev-08) remains UNREVIEWED and unverified; the transcribed symbols, their unit ($/kWh) and the index gamma are provisional pending source audit. No verification of B transcription or downstream science is claimed.","bindings":[{"object_id":"v141-c-R025-theta-BgammaP","node_ids":["pricing.local"],"edge_ids":["v141-c-R025-E001"],"rationale":"B_gamma^P is the TR buyer-side transaction price produced at pricing.local and carried along edge v141-c-R025-E001 (type links) toward settlement.payment, where it fixes the buyer's payment rate. It is modeled as a parameter because in this settlement rule it is a given input rather than a quantity chosen by the payment rule."},{"object_id":"v141-c-R025-theta-SgammaP","node_ids":["pricing.local"],"edge_ids":["v141-c-R025-E001"],"rationale":"S_gamma^P is the TR seller-side transaction price produced at pricing.local and carried along edge v141-c-R025-E001 (type links) toward settlement.payment, where it fixes the seller's receipt rate. It is modeled as a parameter because in this settlement rule it is a given input rather than a quantity chosen by the payment rule."},{"object_id":"v141-c-R025-C001","node_ids":["pricing.local","settlement.payment"],"edge_ids":["v141-c-R025-E001"],"rationale":"The constraint relates the TR transaction prices at pricing.local to the buyer payment rate and seller receipt rate at settlement.payment, which is exactly the relation represented by the frozen edge v141-c-R025-E001 (pricing.local -> settlement.payment, type links)."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"b2b6b274217437564144f2f428b6374fb4f0d770d5f3c52e1cf96b29ca684c25","delivery_payload_sha256":"29ec46a181df5a099a6f467cac5c1ccc89706c21bcefaa020b9b43c942132a0a","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"d70bbf46b352283107e80d846a7d5cacb30276c3f180f78a26a546f2f198c599","scientific_correctness_verified":false}},"quarantined_references":[]}});
